questionvariables.text:
/* Randomize max wait time for the uniform distribution */
b : rand([15, 20, 25, 30, 35, 40, 45, 50, 55, 60]);

/* Calculate height of the PDF (1/b) */
ta1 : 1 / b;

/* Randomize internal bounds for P(c <= X <= d) */
c : rand([2, 3, 4, 5, 6]);
d : c + rand([4, 5, 6, 7, 8, 9]);
d_minus_c : d - c;

/* Calculate target interval probability */
ta2 : d_minus_c / b;

/* Randomize exact value target for part c */
exact_val : rand([7, 8, 9, 11, 12, 13, 14]);

/* Target probability for an exact value in a continuous distribution is always 0 */
ta3 : 0;
